import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['hello_world_log_message_flow_2'],
        name: 'Hello World Log Message Flow 2',
        description: 'Hello World Log Message Flow 2 Description',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['hello_world_log_message_flow_trigger_2'] },
        {
            email_conditions: 'checkpoint=',
            target_table: 'evaluation',
            stop_condition_evaluation: true,
            order: 1,
        }
    ),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['hello_world_log_message_flow_action_2'], annotation: 'Log Hello World Message' },
            {
                log_level: 'info',
                log_message: 'Hello World',
            }
        )
    }
)
